            let end_i = result_value(&result, row_id);
            assert!(
                (end_i - round6(expected_forces[dof])).abs() <= 1.0e-3,
                "end-i row {row_id} value {end_i} must match the direct oracle {}",
                expected_forces[dof]
            );
            let end_j = result_value(&result, &format!("{row_id}:end-j"));
            assert!(
