        let shear_z_end_i = result_value(&result, "result:force:pipe-P-100:shear-z");
        assert!(
            (shear_z_end_i - total_load).abs() <= 1.0e-3 * total_load,
            "end-i shear {shear_z_end_i} must carry the full distributed resultant {total_load}"
        );

